// Marketplace.js
import React, { useState } from 'react';
import '../styles/Marketplace.css';

const templatesData = [
  { id: 1, name: 'Startup Landing', thumbnail: '/templates/startup.png', previewUrl: '/preview/1' },
  { id: 2, name: 'Portfolio', thumbnail: '/templates/portfolio.png', previewUrl: '/preview/2' },
  { id: 3, name: 'E-commerce', thumbnail: '/templates/ecommerce.png', previewUrl: '/preview/3' },
  { id: 4, name: 'Agency', thumbnail: '/templates/agency.png', previewUrl: '/preview/4' },
];

const Marketplace = () => {
  const [selectedTemplate, setSelectedTemplate] = useState(null);

  const handlePreview = (template) => setSelectedTemplate(template);
  const handleClosePreview = () => setSelectedTemplate(null);

  return (
    <div className="marketplace-container">
      <h1 className="marketplace-title">Marketplace Templates</h1>

      <div className="templates-grid">
        {templatesData.map(template => (
          <div key={template.id} className="template-card">
            <div className="template-image-wrapper">
              <img src={template.thumbnail} alt={template.name} className="template-thumbnail"/>
              <div className="template-overlay">
                <button className="preview-button" onClick={() => handlePreview(template)}>Preview</button>
                <button className="select-button">Select</button>
              </div>
            </div>
            <h2 className="template-name">{template.name}</h2>
          </div>
        ))}
      </div>

      {/* Modal Preview */}
      {selectedTemplate && (
        <div className="preview-modal">
          <div className="preview-content">
            <button className="close-button" onClick={handleClosePreview}>✕</button>
            <h2 className="preview-title">{selectedTemplate.name} Preview</h2>
            <iframe 
              src={selectedTemplate.previewUrl} 
              title={selectedTemplate.name} 
              className="preview-iframe"
            />
          </div>
        </div>
      )}
    </div>
  );
};

export default Marketplace;
